response:
**Gates before launch.** If any gate fails, I halt and report.

1. I confirm that `spe/predictions/r04.yaml` and `spe/plans/r04.md` are in the "SPE r04 predict" commit and have not changed since.
2. I run the grader selftest.
   - `grade.py` must score the oracle (answers.json fed back as output) at 50 of 50.
   - It must fail an empty result and a wrong result (a shifted category and a priority off by one).
   - `answers.json` must hold exactly the 50 IDs in `args.tickets`.
   - `judge.md` must rank a known polite reply above a known curt one.
3. I regrade the round 3 runs (40 tickets) with this round's `grade.py` and compare them with the r03 numbers in `spe/prediction-log.md`. Any change there is a grader change, and I log it before launch.
4. I do a dry run with `only: ["B:T001","C2:T001","C2:T017"]`, `trials: 1`, `capUsd: 2` and `topupPerCell: 0`.
   - Every trial must be schema-valid and get a grader row and a judge score.
   - The peek audit must come back clean.
   - The run must show a real spend number.
   - The dry run also replaces the unmeasured estimate of $0.06 per trial. At that rate, 500 base trials cost about $30 of the $40 cap.

If all gates pass, I commit the script as "SPE r04 evaluate (harness)" and launch it with the full args.

**Defaults I chose.** The situation does not give some paths, so I put defaults in args: the runner is `node triage/run.js`, tickets are at `spe/evals/tasks/tickets/{id}.json`, and `grade.py` takes `--inputs <file>`. The dry run will catch any of these that are wrong. The $40 cap covers triage API spend reported by the runner plus judge estimates. It does not count the tokens of the subagents that run the harness.

```js
export const meta = {
  name: "spe-triage-eval",
  description:
    "SPE eval for the triage agent. Runs configs B and C2 over the ticket set with repeated trials, grades category and priority with the code grader, judges reply tone blind with Opus, tops up split cells, and ends with failure analysis and a completeness critic.",
  phases: [
    { title: "Trials" },
    { title: "Audit" },
    { title: "Grade" },
    { title: "Top-up" },
    { title: "Judge" },
    { title: "Synthesis" },
  ],
};

// The round lives here and nowhere else.
const ROUND = 4;
const RR = String(ROUND).padStart(2, "0");
const RUN_DIR = `spe/runs/r${RR}`;

const A = {
  configs: ["B", "C2"],
  tickets: [], // 50 ticket IDs, passed in by the launcher
  expectedTickets: 50,
  trials: 5,
  capUsd: 40,
  judgeReserveUsd: 6, // held back from trials so the judge always runs
  trialCostEstUsd: 0.06, // unmeasured, the dry run replaces it
  judgeCostEstUsd: 0.1, // per ticket batch, unmeasured
  topupPerCell: 3,
  topupMaxTotal: 60,
  graderErrorHalt: 0.1,
  voidHalt: 0.05,
  only: null, // for example ["B:T001", "C2:T017"] in the dry run
  runner: "node triage/run.js",
  gradeCmd: "python spe/evals/graders/grade.py --answers spe/evals/tasks/answers.json --json",
  ticketPath: "spe/evals/tasks/tickets/{id}.json",
  model: "opus",
  ...(args && typeof args === "object" ? args : {}),
};

const TRIAL_LIMIT = A.capUsd - A.judgeReserveUsd;
const FORBIDDEN = ["spe/evals/", "spe/predictions/", "spe/plans/", "spe/spec/", "answers.json", "grade.py", "judge.md"];
const GREP_PATTERN = "spe/(evals|predictions|plans|spec)/|answers\\.json|grade\\.py|judge\\.md";

// ---------- cells ----------
const cells = A.only
  ? A.only.map((k) => {
      const [config, ticket] = k.split(":");
      return { config, ticket };
    })
  : A.configs.flatMap((config) => A.tickets.map((ticket) => ({ config, ticket })));

if (!A.only && A.tickets.length !== A.expectedTickets) {
  throw new Error(`Expected ${A.expectedTickets} tickets in args.tickets, got ${A.tickets.length}.`);
}
for (const c of cells) {
  if (!A.configs.includes(c.config) || !c.ticket) throw new Error(`Bad cell ${c.config}:${c.ticket}`);
}

// ---------- budget ----------
const budget = { spent: 0, reserved: 0, skips: [] };
const usd = (x) => x.toFixed(2);
function reserve(kind, key, est, limit) {
  if (budget.spent + budget.reserved + est > limit) {
    budget.skips.push({ kind, key, est_usd: est, spent_usd: Number(usd(budget.spent)) });
    return false;
  }
  budget.reserved += est;
  return true;
}
function settle(est, actual) {
  budget.reserved -= est;
  budget.spent += Number.isFinite(actual) && actual >= 0 ? actual : est;
}

// ---------- helpers ----------
const isLive = (t) => t.status === "completed" && !t.voided;
const isGraded = (t) => isLive(t) && typeof t.category_ok === "boolean" && !t.grade_error;
const passed = (t) => t.category_ok === true && t.priority_ok === true;
const sameCell = (t, c) => t.config === c.config && t.ticket === c.ticket;
const count = (xs, f) => xs.filter(f).length;
const rate = (xs, f) => (xs.length ? Number((count(xs, f) / xs.length).toFixed(3)) : null);
const mean = (xs) => (xs.length ? Number((xs.reduce((a, b) => a + b, 0) / xs.length).toFixed(2)) : null);
const median = (xs) => {
  if (!xs.length) return null;
  const s = xs.slice().sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2;
};
function groupBy(xs, f) {
  const out = {};
  for (const x of xs) (out[f(x)] = out[f(x)] || []).push(x);
  return out;
}
function seeded(str) {
  let h = 2166136261;
  for (const ch of str) {
    h ^= ch.charCodeAt(0);
    h = Math.imul(h, 16777619);
  }
  return () => {
    h = (h + 0x6d2b79f5) | 0;
    let x = Math.imul(h ^ (h >>> 15), 1 | h);
    x = (x + Math.imul(x ^ (x >>> 7), 61 | x)) ^ x;
    return ((x ^ (x >>> 14)) >>> 0) / 4294967296;
  };
}
function shuffle(xs, seed) {
  const r = seeded(seed);
  const a = xs.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(r() * (i + 1));
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------- schemas ----------
const TRIAL_SCHEMA = {
  type: "object",
  required: ["status", "result_path", "transcript_path", "label", "reply", "metrics", "commands_run", "error"],
  properties: {
    status: { enum: ["completed", "harness_error", "rate_limited"] },
    result_path: { type: "string" },
    transcript_path: { type: "string" },
    label: {
      type: ["object", "null"],
      properties: { category: { type: "string" }, priority: { type: "string" } },
    },
    reply: { type: ["string", "null"] },
    metrics: {
      type: "object",
      required: ["runtime_s", "tool_calls", "tool_errors", "input_tokens", "output_tokens", "cost_usd"],
      properties: {
        runtime_s: { type: "number" },
        tool_calls: { type: "integer" },
        tool_errors: { type: "integer" },
        input_tokens: { type: "integer" },
        output_tokens: { type: "integer" },
        cost_usd: { type: "number" },
      },
    },
    commands_run: { type: "array", items: { type: "string" } },
    error: { type: ["string", "null"] },
  },
};
const AUDIT_SCHEMA = {
  type: "object",
  required: ["checked", "missing", "hits"],
  properties: {
    checked: { type: "integer" },
    missing: { type: "array", items: { type: "string" } },
    hits: {
      type: "array",
      items: {
        type: "object",
        required: ["transcript_path", "pattern", "excerpt"],
        properties: { transcript_path: { type: "string" }, pattern: { type: "string" }, excerpt: { type: "string" } },
      },
    },
  },
};
const GRADE_SCHEMA = {
  type: "object",
  required: ["grader_sha", "results"],
  properties: {
    grader_sha: { type: "string" },
    results: {
      type: "array",
      items: {
        type: "object",
        required: ["result_path", "category_ok", "priority_ok", "error"],
        properties: {
          result_path: { type: "string" },
          category_ok: { type: ["boolean", "null"] },
          priority_ok: { type: ["boolean", "null"] },
          error: { type: ["string", "null"] },
        },
      },
    },
  },
};
const JUDGE_SCHEMA = {
  type: "object",
  required: ["scores"],
  properties: {
    scores: {
      type: "array",
      items: {
        type: "object",
        required: ["id", "tone_score", "tone_pass", "reason"],
        properties: {
          id: { type: "string" },
          tone_score: { type: "integer", minimum: 1, maximum: 5 },
          tone_pass: { type: "boolean" },
          reason: { type: "string" },
        },
      },
    },
  },
};
const FAIL_SCHEMA = {
  type: "object",
  required: ["failure_types", "grader_suspects", "notes"],
  properties: {
    failure_types: {
      type: "array",
      items: {
        type: "object",
        required: ["f_id", "name", "kind", "what", "how_to_spot", "seen_in", "count_by_config", "proposed_fix"],
        properties: {
          f_id: { type: "string" },
          name: { type: "string" },
          kind: { type: "string" },
          what: { type: "string" },
          how_to_spot: { type: "string" },
          seen_in: { type: "array", items: { type: "string" } },
          count_by_config: { type: "object" },
          proposed_fix: { type: "string" },
        },
      },
    },
    grader_suspects: { type: "array", items: { type: "string" } },
    notes: { type: "string" },
  },
};
const CRITIC_SCHEMA = {
  type: "object",
  required: ["every_prediction_measured", "unmeasured", "gaps"],
  properties: {
    every_prediction_measured: { type: "boolean" },
    unmeasured: { type: "array", items: { type: "string" } },
    gaps: {
      type: "array",
      items: {
        type: "object",
        required: ["what", "severity", "fix"],
        properties: { what: { type: "string" }, severity: { enum: ["high", "medium", "low"] }, fix: { type: "string" } },
      },
    },
  },
};

// ---------- prompts ----------
function trialPrompt(c, n) {
  const out = `${RUN_DIR}/${c.config}/${c.ticket}/t${n}`;
  return [
    "You are a trial runner for an evaluation. Do exactly one thing.",
    "",
    "Run this command from the repository root and wait for it to finish:",
    `  ${A.runner} --config ${c.config} --ticket ${c.ticket} --trial ${n} --out ${out}`,
    "",
    "Rules:",
    `- After the command finishes, read only ${out}/result.json. Do not open, list, grep, or cat any other path.`,
    "- Never touch spe/evals/, spe/predictions/, spe/plans/, or spe/spec/.",
    "- Do not retry with changed arguments. Do not fix, judge, or rewrite the triage output.",
    '- If the command fails with HTTP 429 or a rate-limit message, set status "rate_limited". If it fails for another reason, set status "harness_error". Put the error text in error.',
    `- Copy label, reply, and metrics from result.json. Set result_path to ${out}/result.json and transcript_path to ${out}/transcript.jsonl.`,
    "- List every shell command you ran in commands_run, exactly as you ran it.",
  ].join("\n");
}
function auditPrompt(paths) {
  return [
    "You audit eval transcripts for reads of the answer key. Do not open any file under spe/evals/ or spe/predictions/ yourself. Do not edit any file.",
    `1. Run: grep -rnE '${GREP_PATTERN}' ${RUN_DIR} --include=transcript.jsonl`,
    "2. For each match, report transcript_path, the matched text as pattern, and an excerpt of at most 200 characters.",
    "3. Check that each transcript below exists. Report missing ones in missing, and the number that exist in checked.",
    "",
    ...paths,
  ].join("\n");
}
function gradePrompt(paths, tag) {
  const listFile = `${RUN_DIR}/grade-inputs-${tag}.txt`;
  return [
    "You run the code grader for an eval. Do not grade anything yourself.",
    `1. Write these ${paths.length} paths, one per line, to ${listFile}.`,
    `2. Run: ${A.gradeCmd} --inputs ${listFile}`,
    "3. Run: git hash-object spe/evals/graders/grade.py and put the output in grader_sha.",
    "4. Copy the grader output into results, one entry per path, with values unchanged. If the grader errors on a path, put the error text in that entry's error field and set the booleans to null.",
    "Do not edit grade.py or answers.json. Do not rerun with different flags.",
    "",
    ...paths,
  ].join("\n");
}
function judgePrompt(ticket, items) {
  return [
    "You are the tone judge for an eval of a support-ticket triage agent.",
    "Read spe/evals/graders/judge.md and apply its rubric exactly.",
    `Read the ticket at ${A.ticketPath.replace("{id}", ticket)}.`,
    `Below are ${items.length} draft first replies to that ticket, labeled ${items[0].id} to ${items[items.length - 1].id}. They come from different agent configurations in random order. You are not told which is which, and you should not guess.`,
    "Score each reply for tone only. Do not score the category or priority. Return one score per id. Do not edit any file.",
    "",
    ...items.flatMap(({ id, t }) => [`--- ${id} ---`, t.reply, ""]),
  ].join("\n");
}

// ---------- stages ----------
async function runTrial(c, n, phaseTitle) {
  const key = `${c.config}:${c.ticket}:t${n}`;
  const base = { key, config: c.config, ticket: c.ticket, trial: n };
  if (!reserve("trial", key, A.trialCostEstUsd, TRIAL_LIMIT)) return { ...base, status: "skipped_budget" };
  let r;
  try {
    r = await agent(trialPrompt(c, n), { label: `trial ${key}`, phase: phaseTitle, schema: TRIAL_SCHEMA, model: A.model });
  } catch (e) {
    settle(A.trialCostEstUsd, null);
    return { ...base, status: "harness_error", error: String((e && e.message) || e) };
  }
  if (!r || typeof r !== "object") {
    settle(A.trialCostEstUsd, null);
    return { ...base, status: "harness_error", error: "no structured result" };
  }
  settle(A.trialCostEstUsd, r.metrics && r.metrics.cost_usd);
  const t = { ...r, ...base, voided: null };
  const bad = (r.commands_run || []).find((cmd) => FORBIDDEN.some((f) => cmd.includes(f)));
  if (bad) t.voided = `trial command touched a forbidden path: ${bad.slice(0, 160)}`;
  return t;
}

function logWave(name, wave) {
  log(
    `${name}: ${count(wave, (t) => t.status === "completed")} completed, ` +
      `${count(wave, (t) => t.status === "harness_error")} harness errors, ` +
      `${count(wave, (t) => t.status === "rate_limited")} rate limited, ` +
      `${count(wave, (t) => t.status === "skipped_budget")} skipped for budget, ` +
      `${count(wave, (t) => t.voided)} voided. Spent $${usd(budget.spent)} of $${A.capUsd}.`
  );
}

async function audit(list, phaseTitle) {
  const targets = list.filter(isLive);
  if (!targets.length) return;
  const res = await agent(auditPrompt(targets.map((t) => t.transcript_path)), {
    label: `peek audit (${targets.length})`,
    phase: phaseTitle,
    schema: AUDIT_SCHEMA,
    model: A.model,
  });
  const hits = new Map((res.hits || []).map((h) => [h.transcript_path, h]));
  const missing = new Set(res.missing || []);
  for (const t of targets) {
    if (hits.has(t.transcript_path)) t.voided = `transcript matched ${hits.get(t.transcript_path).pattern}`;
    else if (missing.has(t.transcript_path)) t.voided = "transcript missing, so the peek scan could not clear it";
  }
  log(`Audit: ${hits.size} transcripts matched a forbidden path, ${missing.size} missing.`);
}

let graderSha = null;
async function grade(list, phaseTitle, tag) {
  const targets = list.filter(isLive);
  if (!targets.length) return 0;
  const res = await agent(gradePrompt(targets.map((t) => t.result_path), tag), {
    label: `code grader (${targets.length})`,
    phase: phaseTitle,
    schema: GRADE_SCHEMA,
    model: A.model,
  });
  if (graderSha && res.grader_sha !== graderSha) log(`Grader hash changed mid-run: ${graderSha} to ${res.grader_sha}`);
  graderSha = res.grader_sha;
  const rows = new Map((res.results || []).map((r) => [r.result_path, r]));
  let errors = 0;
  for (const t of targets) {
    const r = rows.get(t.result_path);
    if (!r || r.error || typeof r.category_ok !== "boolean" || typeof r.priority_ok !== "boolean") {
      t.grade_error = (r && r.error) || "no grader row";
      errors++;
    } else {
      t.category_ok = r.category_ok;
      t.priority_ok = r.priority_ok;
    }
  }
  log(`Grade (${tag}): ${targets.length - errors} graded, ${errors} grader errors.`);
  return errors / targets.length;
}

function summarize(list) {
  const out = {};
  for (const config of A.configs) {
    const mine = list.filter((t) => t.config === config);
    const live = mine.filter(isLive);
    const graded = live.filter(isGraded);
    const judged = live.filter((t) => typeof t.tone_pass === "boolean");
    const m = live.map((t) => t.metrics).filter(Boolean);
    out[config] = {
      attempted: mine.length,
      completed: live.length,
      voided: count(mine, (t) => t.voided),
      harness_errors: count(mine, (t) => t.status === "harness_error"),
      rate_limited: count(mine, (t) => t.status === "rate_limited"),
      skipped_budget: count(mine, (t) => t.status === "skipped_budget"),
      grader_errors: count(live, (t) => t.grade_error),
      category_acc: rate(graded, (t) => t.category_ok),
      priority_acc: rate(graded, (t) => t.priority_ok),
      both_acc: rate(graded, passed),
      tone_pass_rate: rate(judged, (t) => t.tone_pass),
      tone_mean: mean(judged.map((t) => t.tone_score)),
      runtime_s_median: median(m.map((x) => x.runtime_s)),
      tool_calls_mean: mean(m.map((x) => x.tool_calls)),
      tool_errors_per_trial: mean(m.map((x) => x.tool_errors)),
      tokens_mean: mean(m.map((x) => x.input_tokens + x.output_tokens)),
      cost_usd_total: Number(usd(m.reduce((a, x) => a + (x.cost_usd || 0), 0))),
    };
  }
  return out;
}

function compact(t) {
  const { key, config, ticket, trial, status, voided, category_ok, priority_ok, grade_error, tone_score, tone_pass, judge_error, metrics, result_path, error, retried_after } = t;
  return { key, config, ticket, trial, status, voided, category_ok, priority_ok, grade_error, tone_score, tone_pass, judge_error, metrics, result_path, error, retried_after };
}

const halts = [];
function finish(all, extra = {}) {
  const base = all.filter((t) => t.trial <= A.trials);
  const cellConsistency = {};
  for (const config of A.configs) {
    const mine = cells.filter((c) => c.config === config);
    const allPass = mine.filter((c) => {
      const g = base.filter((t) => sameCell(t, c) && isGraded(t));
      return g.length > 0 && g.every(passed);
    });
    cellConsistency[config] = mine.length ? Number((allPass.length / mine.length).toFixed(3)) : null;
  }
  return {
    round: ROUND,
    status: halts.length ? "halted" : "complete",
    halts,
    grader_sha: graderSha,
    judge_note: "The judge is Opus, the same model family as the agent under test. A judge from a different family was not available.",
    spend: { spent_usd: Number(usd(budget.spent)), cap_usd: A.capUsd, trial_limit_usd: TRIAL_LIMIT, skipped: budget.skips.length },
    metrics: { base: summarize(base), with_topup: summarize(all), cells_all_pass_base: cellConsistency },
    skips: budget.skips,
    voids: all.filter((t) => t.voided).map((t) => ({ key: t.key, reason: t.voided })),
    trials: all.map(compact),
    ...extra,
  };
}

// ---------- run ----------
log(`Round ${ROUND}: ${cells.length} cells, ${A.trials} trials each, cap $${A.capUsd} (trials up to $${TRIAL_LIMIT}).`);

phase("Trials");
let trials = [];
for (let n = 1; n <= A.trials; n++) {
  // One wave per trial index, so a budget stop leaves the cells balanced.
  const wave = await parallel(cells.map((c) => () => runTrial(c, n, "Trials")));
  trials.push(...wave);
  logWave(`Trial wave ${n} of ${A.trials}`, wave);
}
const retryable = trials.filter((t) => t.status === "harness_error" || t.status === "rate_limited");
if (retryable.length) {
  const retried = await parallel(retryable.map((t) => () => runTrial({ config: t.config, ticket: t.ticket }, t.trial, "Trials")));
  const byKey = new Map(retried.map((r, i) => [r.key, { ...r, retried_after: retryable[i].status }]));
  trials = trials.map((t) => byKey.get(t.key) || t);
  logWave("Retry of harness errors and rate limits", retried);
}

phase("Audit");
await audit(trials, "Audit");
const voidRate = trials.length ? count(trials, (t) => t.voided) / trials.length : 0;
if (voidRate > A.voidHalt) {
  halts.push(`Possible answer-key leak: ${(voidRate * 100).toFixed(1)}% of trials voided for peeking.`);
  return finish(trials);
}

phase("Grade");
const gradeErr = await grade(trials, "Grade", "base");
if (gradeErr > A.graderErrorHalt) {
  halts.push(`Grader looks broken: ${(gradeErr * 100).toFixed(1)}% of trials got no grade.`);
  return finish(trials);
}

phase("Top-up");
const splitCells = cells.filter((c) => {
  const g = trials.filter((t) => sameCell(t, c) && isGraded(t));
  return g.some(passed) && g.some((t) => !passed(t));
});
log(`Top-up: ${splitCells.length} split cells, up to ${A.topupPerCell} extra trials each, ${A.topupMaxTotal} total.`);
const topups = [];
let topupLeft = A.topupMaxTotal;
for (let i = 1; i <= A.topupPerCell && topupLeft > 0 && splitCells.length; i++) {
  const batch = splitCells.slice(0, topupLeft);
  topupLeft -= batch.length;
  const wave = await parallel(batch.map((c) => () => runTrial(c, A.trials + i, "Top-up")));
  topups.push(...wave);
  logWave(`Top-up wave ${i}`, wave);
}
if (topups.length) {
  await audit(topups, "Top-up");
  await grade(topups, "Top-up", "topup");
}
const all = [...trials, ...topups];

phase("Judge");
const live = all.filter(isLive);
for (const t of live) {
  if (typeof t.reply !== "string" || !t.reply.trim()) {
    t.tone_score = 1;
    t.tone_pass = false;
    t.tone_reason = "empty reply";
  }
}
const byTicket = groupBy(live.filter((t) => t.tone_pass === undefined), (t) => t.ticket);
await parallel(
  Object.entries(byTicket).map(([ticket, list]) => async () => {
    if (!reserve("judge", ticket, A.judgeCostEstUsd, A.capUsd)) {
      list.forEach((t) => (t.judge_error = "skipped for budget"));
      return;
    }
    const items = shuffle(list, `${RR}:${ticket}`).map((t, i) => ({ id: `R${i + 1}`, t }));
    let res;
    try {
      res = await agent(judgePrompt(ticket, items), { label: `tone judge ${ticket}`, phase: "Judge", schema: JUDGE_SCHEMA, model: "opus" });
    } catch (e) {
      settle(A.judgeCostEstUsd, null);
      items.forEach(({ t }) => (t.judge_error = String((e && e.message) || e)));
      return;
    }
    settle(A.judgeCostEstUsd, null);
    const scores = new Map(((res && res.scores) || []).map((s) => [s.id, s]));
    for (const { id, t } of items) {
