  { label: "completeness critic", phase: "Synthesis", schema: CRITIC_SCHEMA, model: A.model }
);

log(`Done. Spent $${usd(budget.spent)} of $${A.capUsd}. ${budget.skips.length} skips, ${summary.voids.length} voids, ${critic.gaps.length} critic gaps.`);
return { ...summary, failure_analysis: failureAnalysis, critic };
